-- ═══════════════════════════════════════════════════════════════════════════
--  Ecommerce — Supabase (Postgres) schema
-- ═══════════════════════════════════════════════════════════════════════════
--
--  HOW TO APPLY
--    1. Supabase dashboard → SQL Editor → New query → paste → Run.
--       (or)  psql "$SUPABASE_DB_URL" -f supabase/schema.sql
--    2. Then load the catalogue:  psql "$SUPABASE_DB_URL" -f supabase/seed.sql
--
--  Every statement is idempotent, so re-running this file is safe.
--
--  MIGRATION NOTES (MySQL → Postgres)
--    • AUTO_INCREMENT id  →  bigint GENERATED BY DEFAULT AS IDENTITY
--    • ENUM(...)          →  text + CHECK constraint (easier to extend later)
--    • JSON               →  jsonb
--    • TINYINT(1)         →  boolean
--    • The legacy single-item `orders` table from the old database.sql was never
--      read or written by the app and has NOT been carried over. Live customer
--      orders live in customer_orders / customer_order_items.
-- ═══════════════════════════════════════════════════════════════════════════


begin;

-- ─── USERS ─────────────────────────────────────────────────────────────────
create table if not exists public.users (
  id          bigint generated by default as identity primary key,
  name        text        not null,
  email       text        not null unique,
  password    text        not null,               -- bcryptjs hash
  role        text        not null default 'user' check (role in ('user', 'admin')),
  status      text        not null default 'active' check (status in ('active', 'blocked')),
  created_at  timestamptz not null default now()
);

comment on table public.users is
  'Application accounts. Password is a bcryptjs hash; never store plaintext.';


-- ─── PRODUCTS ──────────────────────────────────────────────────────────────
create table if not exists public.products (
  id                 bigint generated by default as identity primary key,
  name               text        not null,
  slug               text        not null unique,
  category           text        not null default 'General',
  brand              text        not null default '',
  price              numeric(12,2) not null default 0 check (price >= 0),
  mrp                numeric(12,2) not null default 0 check (mrp >= 0),   -- "was" price; 0 = none
  image_url          text,
  images             jsonb       not null default '[]'::jsonb,
  description_intro  text        not null default '',
  specifications     jsonb       not null default '{}'::jsonb,

  -- Storefront merchandising
  badge              text        not null default '',
  rating             numeric(2,1) not null default 0 check (rating between 0 and 5),
  review_count       integer     not null default 0 check (review_count >= 0),
  stock              integer     not null default 25 check (stock >= 0),
  is_featured        boolean     not null default false,
  is_deal            boolean     not null default false,
  deal_ends_at       timestamptz,               -- drives the Deal-of-the-Day countdown

  -- Cross-sell. Slugs (not ids) so a bundle survives a product being re-imported.
  -- e.g. '["ecommerce-stylus-pen-2", "ecommerce-usb-c-cable-2m"]'
  bundle_slugs       jsonb       not null default '[]'::jsonb,

  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index if not exists products_category_idx on public.products (category);
create index if not exists products_brand_idx    on public.products (brand);
create index if not exists products_created_idx  on public.products (created_at desc);

comment on column public.products.price is
  'Selling price. 0 means "priced on request" and cannot be bought online.';
comment on column public.products.mrp is
  'Struck-through "was" price. Keep >= price, or 0 for no discount.';
comment on column public.products.bundle_slugs is
  'Slugs of products commonly bought with this one. Rendered as "Frequently Bought Together".';


-- ─── CUSTOMER ORDERS ───────────────────────────────────────────────────────
create table if not exists public.customer_orders (
  id                 bigint generated by default as identity primary key,
  order_no           text        not null unique,
  user_id            bigint      not null references public.users (id) on delete cascade,
  status             text        not null default 'pending'
                       check (status in ('pending','processing','shipped','delivered','cancelled')),
  subtotal           numeric(12,2) not null default 0,
  shipping           numeric(12,2) not null default 0,
  total              numeric(12,2) not null default 0,
  payment_method     text        not null default 'whatsapp'
                       check (payment_method in ('cod','razorpay','whatsapp')),
  payment_status     text        not null default 'pending'
                       check (payment_status in ('pending','paid','failed','refunded')),
  razorpay_order_id  text unique,
  razorpay_payment_id text       not null default '',
  contact_name       text        not null default '',
  contact_phone      text        not null default '',
  address_line       text        not null default '',
  city               text        not null default '',
  state              text        not null default '',
  pincode            text        not null default '',
  notes              text,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index if not exists customer_orders_user_idx   on public.customer_orders (user_id, created_at desc);
create index if not exists customer_orders_status_idx on public.customer_orders (status);


create table if not exists public.customer_order_items (
  id             bigint generated by default as identity primary key,
  order_id       bigint        not null references public.customer_orders (id) on delete cascade,
  product_id     bigint        references public.products (id) on delete set null,
  -- Name / slug / image are denormalised snapshots: an order must stay readable
  -- even after the product is renamed or deleted.
  product_name   text          not null,
  product_slug   text          not null default '',
  product_image  text,
  unit_price     numeric(12,2) not null default 0,
  quantity       integer       not null default 1 check (quantity > 0),
  line_total     numeric(12,2) not null default 0
);

create index if not exists customer_order_items_order_idx on public.customer_order_items (order_id);


-- ─── WISHLIST ──────────────────────────────────────────────────────────────
create table if not exists public.favorites (
  id         bigint generated by default as identity primary key,
  user_id    bigint      not null references public.users (id) on delete cascade,
  product_id bigint      not null references public.products (id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (user_id, product_id)
);

create index if not exists favorites_user_idx on public.favorites (user_id, created_at desc);


-- ─── ADDRESS BOOK ──────────────────────────────────────────────────────────
create table if not exists public.addresses (
  id         bigint generated by default as identity primary key,
  user_id    bigint      not null references public.users (id) on delete cascade,
  label      text        not null default 'Home',
  full_name  text        not null,
  phone      text        not null,
  line1      text        not null,
  line2      text        not null default '',
  city       text        not null,
  state      text        not null,
  pincode    text        not null,
  is_default boolean     not null default false,
  created_at timestamptz not null default now()
);

create index if not exists addresses_user_idx on public.addresses (user_id, is_default desc, id desc);

-- At most one default address per customer. Enforced by the database rather than
-- by application code, so a race between two concurrent saves cannot leave two.
create unique index if not exists addresses_one_default_per_user
  on public.addresses (user_id) where is_default;


-- ─── updated_at MAINTENANCE ────────────────────────────────────────────────
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists products_touch_updated_at on public.products;
create trigger products_touch_updated_at
  before update on public.products
  for each row execute function public.touch_updated_at();

drop trigger if exists customer_orders_touch_updated_at on public.customer_orders;
create trigger customer_orders_touch_updated_at
  before update on public.customer_orders
  for each row execute function public.touch_updated_at();


-- ═══════════════════════════════════════════════════════════════════════════
--  ORDER PLACEMENT
-- ═══════════════════════════════════════════════════════════════════════════
--
--  Supabase's REST layer has no multi-statement transaction, so anything that
--  must be all-or-nothing lives in a Postgres function instead. Prices are
--  re-read from `products` inside the function: the client's idea of what
--  something costs is never trusted.
--
--  The shipping rule below MUST stay in sync with lib/pricing.ts, which is what
--  the browser uses to render the total. Change one, change the other.
-- ═══════════════════════════════════════════════════════════════════════════

create or replace function public.shipping_for(p_subtotal numeric)
returns numeric
language sql
immutable
as $$
  select case
    when p_subtotal <= 0 or p_subtotal >= 25000 then 0
    else 499
  end;
$$;


-- Resolves [{product_id, quantity}] into a priced jsonb array of lines, or raises
-- when a product is missing or priced at zero ("on request"). Shared by both
-- order functions. Returns jsonb rather than a table so callers can test for
-- emptiness with jsonb_array_length without a second round trip.
create or replace function public.resolve_order_lines(p_items jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_line jsonb;
  v_row  record;
  v_out  jsonb := '[]'::jsonb;
begin
  for v_line in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    select p.id, p.name, p.slug, p.image_url, p.price
      into v_row
      from public.products p
     where p.id = greatest(1, floor(coalesce(v_line ->> 'product_id', '0')::numeric))::bigint;

    if not found then
      raise exception 'PRODUCT_UNAVAILABLE:%', coalesce(v_line ->> 'product_id', '');
    end if;

    if coalesce(v_row.price, 0) <= 0 then
      raise exception 'PRICED_ON_REQUEST:%', v_row.name;
    end if;

    v_out := v_out || jsonb_build_object(
      'product_id',    v_row.id,
      'product_name',  v_row.name,
      'product_slug',  v_row.slug,
      'product_image', v_row.image_url,
      'unit_price',    v_row.price,
      'quantity',      least(99, greatest(1, floor(coalesce((v_line ->> 'quantity')::numeric, 1)))),
      'line_total',    v_row.price
                        * least(99, greatest(1, floor(coalesce((v_line ->> 'quantity')::numeric, 1))))
    );
  end loop;

  return v_out;
end;
$$;


-- POST /api/orders — a WhatsApp / request-quote order.
--
-- `p_user_id` is passed explicitly rather than read from auth.uid(): these are
-- called with the service-role key from the server, and that key carries no JWT,
-- so auth.uid() would be NULL.
create or replace function public.place_customer_order(
  p_user_id  bigint,
  p_order_no text,
  p_items    jsonb,
  p_address  jsonb,
  p_notes    text default '',
  p_payment_method text default 'whatsapp'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lines    jsonb;
  v_order_id bigint;
  v_subtotal numeric := 0;
  v_shipping numeric;
  v_total    numeric;
  v_addr     jsonb := coalesce(p_address, '{}'::jsonb);
  v_method   text := coalesce(p_payment_method, 'whatsapp');
begin
  -- Validated here, not in the route, because this is a SECURITY DEFINER
  -- function: the value arrives from the client, and an unknown method would
  -- otherwise be written straight into the orders table. Anything unrecognised
  -- falls back to 'whatsapp' rather than raising — a bad enum value should not
  -- be the reason a customer cannot place an order.
  if v_method not in ('cod', 'razorpay', 'whatsapp') then
    v_method := 'whatsapp';
  end if;

  v_lines := public.resolve_order_lines(p_items);
  if v_lines is null or jsonb_array_length(v_lines) = 0 then
    raise exception 'NO_VALID_ITEMS';
  end if;

  select coalesce(sum((l ->> 'line_total')::numeric), 0)
    into v_subtotal
    from jsonb_array_elements(v_lines) l;

  v_shipping := public.shipping_for(v_subtotal);
  v_total    := v_subtotal + v_shipping;

  insert into public.customer_orders (
    order_no, user_id, status, subtotal, shipping, total, payment_method,
    contact_name, contact_phone, address_line, city, state, pincode, notes
  ) values (
    p_order_no,
    p_user_id,
    'pending',
    v_subtotal,
    v_shipping,
    v_total,
    v_method,
    coalesce(v_addr ->> 'fullName', ''),
    coalesce(v_addr ->> 'phone', ''),
    concat_ws(', ', nullif(v_addr ->> 'line1', ''), nullif(v_addr ->> 'line2', '')),
    coalesce(v_addr ->> 'city', ''),
    coalesce(v_addr ->> 'state', ''),
    coalesce(v_addr ->> 'pincode', ''),
    coalesce(p_notes, '')
  )
  returning id into v_order_id;

  insert into public.customer_order_items (
    order_id, product_id, product_name, product_slug, product_image,
    unit_price, quantity, line_total
  )
  select v_order_id,
         (l ->> 'product_id')::bigint,
         l ->> 'product_name',
         l ->> 'product_slug',
         l ->> 'product_image',
         (l ->> 'unit_price')::numeric,
         (l ->> 'quantity')::integer,
         (l ->> 'line_total')::numeric
    from jsonb_array_elements(v_lines) l;

  return jsonb_build_object(
    'id', v_order_id,
    'order_no', p_order_no,
    'subtotal', v_subtotal,
    'shipping', v_shipping,
    'total', v_total,
    'status', 'pending'
  );
end;
$$;


-- POST /api/payments/verify — a paid (Razorpay) order.
--
-- `p_charged_total` is the amount Razorpay says it took. The function refuses to
-- record the order if the freshly-resolved subtotal disagrees by more than ₹1,
-- which catches a price change between checkout and payment.
create or replace function public.record_paid_order(
  p_user_id             bigint,
  p_order_no            text,
  p_items               jsonb,
  p_address             jsonb,
  p_notes               text,
  p_razorpay_order_id   text,
  p_razorpay_payment_id text,
  p_charged_total       numeric
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_lines    jsonb;
  v_order_id bigint;
  v_subtotal numeric := 0;
  v_shipping numeric;
  v_total    numeric := p_charged_total;
  v_addr     jsonb := coalesce(p_address, '{}'::jsonb);
begin
  v_lines := public.resolve_order_lines(p_items);
  if v_lines is null or jsonb_array_length(v_lines) = 0 then
    raise exception 'NO_VALID_ITEMS';
  end if;

  select coalesce(sum((l ->> 'line_total')::numeric), 0)
    into v_subtotal
    from jsonb_array_elements(v_lines) l;

  if abs(p_charged_total - v_subtotal) > 1 then
    raise exception 'AMOUNT_MISMATCH:%:%', v_subtotal, p_charged_total;
  end if;

  v_shipping := greatest(0, v_total - v_subtotal);

  insert into public.customer_orders (
    order_no, user_id, status, subtotal, shipping, total,
    payment_method, payment_status, razorpay_order_id, razorpay_payment_id,
    contact_name, contact_phone, address_line, city, state, pincode, notes
  ) values (
    p_order_no,
    p_user_id,
    'processing',
    v_subtotal,
    v_shipping,
    v_total,
    'razorpay',
    'paid',
    p_razorpay_order_id,
    coalesce(p_razorpay_payment_id, ''),
    coalesce(v_addr ->> 'fullName', ''),
    coalesce(v_addr ->> 'phone', ''),
    concat_ws(', ', nullif(v_addr ->> 'line1', ''), nullif(v_addr ->> 'line2', '')),
    coalesce(v_addr ->> 'city', ''),
    coalesce(v_addr ->> 'state', ''),
    coalesce(v_addr ->> 'pincode', ''),
    coalesce(p_notes, '')
  )
  returning id into v_order_id;

  insert into public.customer_order_items (
    order_id, product_id, product_name, product_slug, product_image,
    unit_price, quantity, line_total
  )
  select v_order_id,
         (l ->> 'product_id')::bigint,
         l ->> 'product_name',
         l ->> 'product_slug',
         l ->> 'product_image',
         (l ->> 'unit_price')::numeric,
         (l ->> 'quantity')::integer,
         (l ->> 'line_total')::numeric
    from jsonb_array_elements(v_lines) l;

  return jsonb_build_object(
    'id', v_order_id,
    'order_no', p_order_no,
    'total', v_total,
    'status', 'processing',
    'payment_status', 'paid'
  );
end;
$$;


-- POST /api/addresses — insert, promoting the first/default address atomically.
-- p_id is null for "create new". Postgres requires that every parameter after one
-- with a default also has a default, so p_id carries no default and callers pass
-- an explicit null.
create or replace function public.upsert_address(
  p_user_id       bigint,
  p_id            bigint,
  p_label         text,
  p_full_name     text,
  p_phone         text,
  p_line1         text,
  p_line2         text,
  p_city          text,
  p_state         text,
  p_pincode       text,
  p_make_default  boolean default false
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user    bigint := p_user_id;
  v_count   integer;
  v_is_def  boolean;
  v_address bigint;
begin
  if p_make_default then
    update public.addresses set is_default = false where user_id = v_user;
  end if;

  if p_id is null then
    select count(*) into v_count from public.addresses where user_id = v_user;
    -- First address a customer saves is always the default, otherwise checkout
    -- would have nothing to preselect.
    v_is_def := p_make_default or v_count = 0;

    insert into public.addresses (
      user_id, label, full_name, phone, line1, line2, city, state, pincode, is_default
    ) values (
      v_user, coalesce(nullif(p_label, ''), 'Home'), p_full_name, p_phone,
      p_line1, coalesce(p_line2, ''), p_city, p_state, p_pincode, v_is_def
    ) returning id into v_address;
  else
    select is_default into v_is_def from public.addresses where id = p_id and user_id = v_user;
    if not found then
      raise exception 'ADDRESS_NOT_FOUND';
    end if;

    update public.addresses
       set label      = coalesce(nullif(p_label, ''), 'Home'),
           full_name  = p_full_name,
           phone      = p_phone,
           line1      = p_line1,
           line2      = coalesce(p_line2, ''),
           city       = p_city,
           state      = p_state,
           pincode    = p_pincode,
           is_default = coalesce(p_make_default, v_is_def)
     where id = p_id and user_id = v_user
    returning id into v_address;
  end if;

  return v_address;
end;
$$;


-- DELETE /api/addresses/[id] — delete, then never leave the customer with zero defaults.
create or replace function public.delete_address(p_user_id bigint, p_id bigint)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user     bigint := p_user_id;
  v_affected integer;
  v_remaining integer;
begin
  delete from public.addresses where id = p_id and user_id = v_user;
  get diagnostics v_affected = row_count;
  if v_affected = 0 then
    return 0;
  end if;

  select count(*) into v_remaining from public.addresses where user_id = v_user;
  if v_remaining > 0
     and not exists (select 1 from public.addresses where user_id = v_user and is_default) then
    update public.addresses
       set is_default = true
     where id = (select id from public.addresses where user_id = v_user order by id desc limit 1);
  end if;

  return v_affected;
end;
$$;


-- ═══════════════════════════════════════════════════════════════════════════
--  ROW LEVEL SECURITY
-- ═══════════════════════════════════════════════════════════════════════════
--
--  The application talks to Postgres with the service-role key from the server
--  only, which bypasses RLS. Enabling RLS here is therefore defence in depth:
--  if the anon key ever leaks, a browser cannot read customers' orders, wishlists
--  or password hashes. The policies below keep the site useful if you later move
--  data access to the browser — `products` is public, everything else is not.
--
--  The service-role key carries no user JWT, so `auth.uid()` is NULL for
--  server-side calls. Every function above therefore takes `p_user_id`
--  explicitly, and the route handlers pass the id they resolved from the JWT.
--  Callers must never supply a user_id they did not authenticate.
-- ═══════════════════════════════════════════════════════════════════════════

-- The caller's id, as a bigint to match our `users.id` column.
--
-- WHY THIS EXISTS RATHER THAN AN INLINE CAST:
-- `auth.uid()` returns uuid. Postgres has no registered uuid -> bigint cast, so
-- `auth.uid()::bigint` fails with:
--     ERROR: 42846: cannot cast type uuid to bigint
-- Routing through text is the portable form. Having it in one function means
-- there is a single place to get right, instead of four policies that each look
-- correct and each break the whole script.
--
-- Returns NULL when there is no signed-in user, which makes every policy below
-- evaluate to false — the correct answer for an anonymous visitor.
create or replace function public.current_user_id()
returns bigint
language sql
stable
as $$
  select nullif(auth.uid()::text, '')::bigint;
$$;

revoke all on function public.current_user_id() from public;
grant execute on function public.current_user_id() to anon, authenticated, service_role;

alter table public.users              enable row level security;
alter table public.products           enable row level security;
alter table public.customer_orders    enable row level security;
alter table public.customer_order_items enable row level security;
alter table public.favorites          enable row level security;
alter table public.addresses          enable row level security;

-- Nobody may read or write accounts through the public API — auth goes through
-- the server routes only.
drop policy if exists users_public_read on public.users;
create policy users_public_read on public.users
  for select using (false);

-- The catalogue is public. Writes still go through the server's admin check.
drop policy if exists products_public_read on public.products;
create policy products_public_read on public.products
  for select using (true);

-- Everything customer-scoped is readable only by its owner.
--
-- The column is written on the LEFT of each comparison so Postgres can still use
-- the existing user_id indexes; the same expression on the right would force a
-- sequential scan on every request.
drop policy if exists orders_own_read on public.customer_orders;
create policy orders_own_read on public.customer_orders
  for select using (user_id = public.current_user_id());

drop policy if exists order_items_own_read on public.customer_order_items;
create policy order_items_own_read on public.customer_order_items
  for select using (
    exists (select 1 from public.customer_orders o
             where o.id = order_id and o.user_id = public.current_user_id())
  );

drop policy if exists favorites_own_read on public.favorites;
create policy favorites_own_read on public.favorites
  for select using (user_id = public.current_user_id());

drop policy if exists addresses_own_read on public.addresses;
create policy addresses_own_read on public.addresses
  for select using (user_id = public.current_user_id());

-- The order/address functions are SECURITY DEFINER and take the acting user's id
-- explicitly, so they must not be reachable from a browser holding the anon key.
-- Granted to service_role only, which is what the server routes use.
--
-- The signatures below are spelled out in full and must match the CREATE FUNCTION
-- above exactly. Postgres treats a mismatched argument list as a different
-- function, so an arity that has drifted fails with "function does not exist"
-- rather than quietly granting nothing — update both together.
revoke all on function public.place_customer_order(bigint, text, jsonb, jsonb, text, text) from public, anon, authenticated;
revoke all on function public.record_paid_order(bigint, text, jsonb, jsonb, text, text, text, numeric) from public, anon, authenticated;
revoke all on function public.upsert_address(bigint, bigint, text, text, text, text, text, text, text, text, boolean) from public, anon, authenticated;
revoke all on function public.delete_address(bigint, bigint) from public, anon, authenticated;
revoke all on function public.resolve_order_lines(jsonb) from public, anon, authenticated;

grant execute on function public.place_customer_order(bigint, text, jsonb, jsonb, text, text) to service_role;
grant execute on function public.record_paid_order(bigint, text, jsonb, jsonb, text, text, text, numeric) to service_role;
grant execute on function public.upsert_address(bigint, bigint, text, text, text, text, text, text, text, text, boolean) to service_role;
grant execute on function public.delete_address(bigint, bigint) to service_role;
grant execute on function public.resolve_order_lines(jsonb) to service_role;

